// Routes and presentation helpers for the Agent Marketplace pages.
//
// Every value shown comes from src/data/templates.json (generated by the
// catalog's Python reader). These helpers only pick, group and link it; they
// never normalize or invent catalog fields.
import type { WebsiteAuthor, WebsiteTemplate } from "./templates";

export const MARKETPLACE_NAME = "Agent Marketplace";
export const MARKETPLACE_PATH = "/marketplace";

export const templatePath = (key: string): string =>
  `${MARKETPLACE_PATH}/${key}`;

// Template authors have their own /creators/<id> pages; /authors/<slug> is the
// blog's.
export const authorPath = (id: string): string => `/creators/${id}`;

/** Categories in first-seen catalog order, so the gallery order decides. */
export const categoriesOf = (templates: WebsiteTemplate[]): string[] => [
  ...new Set(templates.map((template) => template.category)),
];

/** Templates in one category; "All" counts every template. */
export const categoryCountOf = (
  templates: WebsiteTemplate[],
  category: string,
): number =>
  category === "All"
    ? templates.length
    : templates.filter((template) => template.category === category).length;

export const categorySlug = (category: string): string =>
  category
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");

// --- Media ------------------------------------------------------------------

export interface CatalogMedia {
  kind: string;
  url: string;
  alt?: string | null;
  caption?: string | null;
  poster_url?: string | null;
}

export type RenderableMedia =
  | { kind: "image"; url: string; alt: string; caption?: string }
  | {
      kind: "youtube";
      embedUrl: string;
      url: string;
      alt: string;
      caption?: string;
    }
  | {
      kind: "video";
      url: string;
      alt: string;
      caption?: string;
      posterUrl?: string;
    };

const isHttpUrl = (value: string | null | undefined): value is string => {
  if (!value) return false;
  try {
    const url = new URL(value);
    return url.protocol === "https:" || url.protocol === "http:";
  } catch {
    return false;
  }
};

/** A YouTube watch/share URL as a privacy-enhanced embed URL, else null. */
export const youtubeEmbedUrl = (value: string): string | null => {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    return null;
  }
  const host = url.hostname.replace(/^www\./, "");
  let id: string | null = null;
  if (host === "youtu.be") id = url.pathname.slice(1);
  else if (host === "youtube.com" || host === "m.youtube.com") {
    if (url.pathname === "/watch") id = url.searchParams.get("v");
    else {
      const match = /^\/(?:embed|shorts)\/([^/]+)/.exec(url.pathname);
      id = match?.[1] ?? null;
    }
  }
  if (!id || !/^[\w-]{6,}$/.test(id)) return null;
  return `https://www.youtube-nocookie.com/embed/${id}`;
};

/**
 * The media entries a page can draw, in catalog order. Unsupported kinds and
 * entries without a usable URL are skipped, so the page falls back to its
 * example panel instead of a broken frame.
 */
export const renderableMedia = (
  media: readonly CatalogMedia[] | null | undefined,
  fallbackAlt: string,
): RenderableMedia[] => {
  const items: RenderableMedia[] = [];
  for (const entry of media ?? []) {
    if (!isHttpUrl(entry.url)) continue;
    const alt = entry.alt?.trim() || fallbackAlt;
    const caption = entry.caption?.trim() || undefined;
    if (entry.kind === "image") {
      items.push({ kind: "image", url: entry.url, alt, caption });
    } else if (entry.kind === "video") {
      const embedUrl = youtubeEmbedUrl(entry.url);
      if (embedUrl) {
        items.push({ kind: "youtube", embedUrl, url: entry.url, alt, caption });
      } else {
        items.push({
          kind: "video",
          url: entry.url,
          alt,
          caption,
          posterUrl: isHttpUrl(entry.poster_url) ? entry.poster_url : undefined,
        });
      }
    }
  }
  return items;
};

// --- Authors ----------------------------------------------------------------

export interface AuthorLink {
  label: string;
  url: string;
}

/** The Agenta team's own author id; its templates are the official ones. */
export const AGENTA_AUTHOR_ID = "agenta";

export interface AuthorProfile {
  id: string;
  name: string;
  official: boolean;
  bio?: string;
  avatar?: string;
  initials: string;
  links: AuthorLink[];
}

export const initialsOf = (name: string): string =>
  name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]!.toUpperCase())
    .join("");

/** One creator profile per template author, keeping only web links and avatars. */
export const authorProfiles = (
  templateAuthors: readonly WebsiteAuthor[],
): AuthorProfile[] =>
  templateAuthors
    .map((author) => {
      const rawAvatar = (author as { avatar_url?: string | null }).avatar_url;
      return {
        id: author.id,
        name: author.name,
        official: author.id === AGENTA_AUTHOR_ID,
        bio: author.bio,
        avatar:
          isHttpUrl(rawAvatar) || /^\/(?!\/)/.test(rawAvatar ?? "")
            ? (rawAvatar ?? undefined)
            : undefined,
        initials: initialsOf(author.name),
        links: author.links
          .filter((link) => isHttpUrl(link.url))
          .map((link) => ({
            label: link.label ?? link.kind,
            url: link.url,
          })),
      };
    })
    .sort((a, b) => a.name.localeCompare(b.name));

// --- Apps, steps and setup (template page and index cards) -----------------

// Display names for the connection slugs the catalog uses. An unknown slug
// falls back to its own text, so a new connection never breaks a page.
const APP_NAMES: Record<string, string> = {
  attio: "Attio",
  confluence: "Confluence",
  datadog: "Datadog",
  discord: "Discord",
  github: "GitHub",
  gitlab: "GitLab",
  gmail: "Gmail",
  googlecalendar: "Google Calendar",
  googledrive: "Google Drive",
  hubspot: "HubSpot",
  intercom: "Intercom",
  jira: "Jira",
  linear: "Linear",
  newrelic: "New Relic",
  notion: "Notion",
  pagerduty: "PagerDuty",
  posthog: "PostHog",
  salesforce: "Salesforce",
  sentry: "Sentry",
  slack: "Slack",
  telegram: "Telegram",
  zendesk: "Zendesk",
};

// Simple Icons (CC0) marks in public/logos/tools/; each needs --brand-<slug> in tokens.css.
const APP_LOGOS = new Set([
  "confluence",
  "datadog",
  "discord",
  "github",
  "gitlab",
  "gmail",
  "googlecalendar",
  "googledrive",
  "hubspot",
  "intercom",
  "jira",
  "linear",
  "newrelic",
  "notion",
  "pagerduty",
  "posthog",
  "salesforce",
  "sentry",
  "slack",
  "telegram",
  "zendesk",
]);

export interface TemplateApp {
  slug: string;
  name: string;
  /** Self-hosted logo path; undefined draws the app's initial instead. */
  logo?: string;
}

export const appName = (slug: string): string => APP_NAMES[slug] ?? slug;

const toApp = (slug: string): TemplateApp => ({
  slug,
  name: appName(slug),
  logo: APP_LOGOS.has(slug) ? `/logos/tools/${slug}.svg` : undefined,
});

/** The apps a template connects to: each connection's primary app, once. */
export const appsOf = (template: WebsiteTemplate): TemplateApp[] =>
  [
    ...new Set(
      template.connections.flatMap((connection) =>
        connection.primary ? [connection.primary.slug] : [],
      ),
    ),
  ].map(toApp);

/** "GitHub", "GitHub and Slack", "GitHub, Linear and Slack". */
export const joinNames = (names: string[]): string =>
  names.length > 1
    ? `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}`
    : (names[0] ?? "");

/** The text the index search matches: name, summary, description and apps. */
export const searchTextOf = (template: WebsiteTemplate): string =>
  [
    template.name,
    template.summary,
    template.description,
    ...appsOf(template).map((app) => app.name),
  ]
    .join(" ")
    .toLowerCase();

/** One row of "How it works": the trigger, then one step per connection. */
export type HowStep =
  | { kind: "trigger"; text: string }
  | {
      kind: "connection";
      number: number;
      role: string;
      app?: TemplateApp;
      scope?: string;
      optional: boolean;
    };

export const howItWorksOf = (template: WebsiteTemplate): HowStep[] => [
  ...(template.trigger_description
    ? [{ kind: "trigger" as const, text: template.trigger_description }]
    : []),
  ...template.connections.map((connection, i) => ({
    kind: "connection" as const,
    number: i + 1,
    role: connection.role,
    app: connection.primary ? toApp(connection.primary.slug) : undefined,
    scope: connection.primary?.scope || undefined,
    optional: !connection.required,
  })),
];

/** A how-it-works row as one sentence (the markdown twin). */
export const howStepSentence = (step: HowStep): string =>
  step.kind === "trigger"
    ? step.text
    : `${step.role}${step.app ? ` with ${step.app.name}` : ""}${step.optional ? " (optional)" : ""}.`;

export interface TemplateTool {
  name: string;
  description: string;
  app?: TemplateApp;
}

/** Every tool the template's connections grant, with the app it belongs to. */
export const toolsOf = (template: WebsiteTemplate): TemplateTool[] =>
  template.connections.flatMap((connection) =>
    (connection.primary?.tools ?? []).map((tool) => ({
      name: tool.name,
      description: tool.description,
      app: connection.primary ? toApp(connection.primary.slug) : undefined,
    })),
  );

/** Apps across the catalog with how many templates use each, most used first. */
export const appFacetsOf = (
  all: readonly WebsiteTemplate[],
): { app: TemplateApp; count: number }[] => {
  const counts = new Map<string, number>();
  for (const template of all) {
    for (const app of appsOf(template)) {
      counts.set(app.slug, (counts.get(app.slug) ?? 0) + 1);
    }
  }
  return [...counts]
    .map(([slug, count]) => ({ app: toApp(slug), count }))
    .sort((a, b) => b.count - a.count || a.app.name.localeCompare(b.app.name));
};

/** Index link that opens the catalog on one category. */
export const categoryPath = (category: string): string =>
  `${MARKETPLACE_PATH}?category=${encodeURIComponent(category)}#catalog`;

export interface SetupStep {
  title: string;
  text: string;
}

/** Generated setup steps (the catalog has no setup field). */
export const setupStepsOf = (template: WebsiteTemplate): SetupStep[] => {
  const names = appsOf(template).map((app) => app.name);
  return [
    {
      title: "Use it for free",
      text: "Agenta creates the agent from this template in your workspace.",
    },
    ...(names.length > 0
      ? [
          {
            title: `Connect ${joinNames(names)}`,
            text: "Each app connects from the setup screen.",
          },
        ]
      : []),
    {
      title: "Test, then let it run",
      text: template.trigger
        ? "Run it once to check the result. Then the trigger takes over."
        : "Run it once to check the result.",
    },
  ];
};

export interface Requirement {
  label: string;
  note?: string;
  app: TemplateApp;
}

/** Sidebar "What it needs": one account per connection. */
export const requirementsOf = (template: WebsiteTemplate): Requirement[] => {
  const seen = new Set<string>();
  const accounts: Requirement[] = [];
  for (const connection of template.connections) {
    const slug = connection.primary?.slug;
    if (!slug || seen.has(slug)) continue;
    seen.add(slug);
    accounts.push({
      label: `${appName(slug)} account`,
      note: connection.required ? undefined : "Optional",
      app: toApp(slug),
    });
  }
  return accounts;
};

/** Up to three other templates from the same category, in catalog order. */
export const relatedTemplatesOf = (
  template: WebsiteTemplate,
  all: readonly WebsiteTemplate[],
): WebsiteTemplate[] =>
  all
    .filter(
      (other) =>
        other.key !== template.key && other.category === template.category,
    )
    .slice(0, 3);

export const ctaHeadlineOf = (template: WebsiteTemplate): string =>
  `Start with the ${template.name} template`;

